return ['domain'=>'zinn-cache','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'hi_IN','project-id-version'=>'zinn-cache','pot-creation-date'=>'2026-09-02T07:33:02+00:00','po-revision-date'=>'2026-09-02T07:33:02+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache'=>'Zinn® Cache','https://zinndigital.com/wordpress-plugins/zinn-cache'=>'https://zinndigital.com/wordpress-plugins/zinn-cache','For sites hosted with Zinn Digital®. Controls the page cache your Zinn® server already provides — smart auto-purge on content change, remote purge from your Zinn® dashboard, a Redis object-cache toggle, safe WordPress/WooCommerce exclusions, and one-click admin login. This is a cache controller, not a cache engine. Hosting elsewhere? Install Zinn® Cache Engine instead.'=>'Zinn Digital® के साथ होस्ट की गई साइटों के लिए। पेज कैश को नियंत्रित करता है जो आपका Zinn® सर्वर पहले से प्रदान करता है — सामग्री में बदलाव होने पर स्मार्ट ऑटो-पर्ज, आपके Zinn® डैशबोर्ड से रिमोट पर्ज, एक Redis ऑब्जेक्ट-कैश टॉगल, सुरक्षित WordPress/WooCommerce अपवर्जन, और एक-क्लिक एडमिन लॉगिन। यह एक कैश कंट्रोलर है, कैश इंजन नहीं। कहीं और होस्टिंग है? इसके बजाय Zinn® Cache Engine इंस्टॉल करें।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','You are not allowed to purge the cache.'=>'आपको कैश पर्ज करने की अनुमति नहीं है।','Cache purge requested.'=>'कैश पर्ज का अनुरोध किया गया।','Zinn® Cache: another object-cache drop-in is installed, so the Redis object cache is not managed by this plugin.'=>'Zinn® कैश: एक अन्य ऑब्जेक्ट-कैश ड्रॉप-इन स्थापित है, इसलिए Redis ऑब्जेक्ट कैश इस प्लगइन द्वारा प्रबंधित नहीं किया जाता है।','Full-page cache (LiteSpeed)'=>'फुल-पेज कैश (LiteSpeed)','Enable LSCache control'=>'LSCache नियंत्रण सक्षम करें','Send LiteSpeed cache-control and tag headers on cacheable pages.'=>'कैश-योग्य पेजों पर LiteSpeed कैश-कंट्रोल और टैग हेडर भेजें।','Public cache lifetime (seconds)'=>'सार्वजनिक कैश अवधि (सेकंड)','Object cache (Redis)'=>'ऑब्जेक्ट कैश (Redis)','Enable Redis object cache'=>'Redis ऑब्जेक्ट कैश सक्षम करें','Install the Redis object-cache drop-in (requires the phpredis extension).'=>'Redis ऑब्जेक्ट-कैश ड्रॉप-इन इंस्टॉल करें (phpredis एक्सटेंशन आवश्यक है)।','Redis host'=>'Redis होस्ट','Redis port'=>'Redis पोर्ट','Redis database'=>'Redis डेटाबेस','Redis key prefix'=>'Redis की उपसर्ग','Automatic purging'=>'स्वचालित पर्जिंग','Smart auto-purge'=>'स्मार्ट स्वतः-पर्ज','Purge affected pages automatically when content changes.'=>'कंटेंट बदलने पर प्रभावित पेजों को स्वचालित रूप से पर्ज करें।','Purge on updates'=>'अपडेट पर पर्ज करें','Purge everything after core, plugin, or theme updates.'=>'कोर, प्लगइन या थीम अपडेट के बाद सब कुछ पर्ज करें।','Cache exclusions'=>'कैश अपवाद','Sensible WordPress and WooCommerce defaults are always applied (cart, checkout, my-account, logged-in and session pages are never cached). Add extra rules below, one per line.'=>'समझदारीपूर्ण WordPress और WooCommerce डिफ़ॉल्ट हमेशा लागू होते हैं (कार्ट, चेकआउट, my-account, लॉग-इन और सेशन पेज कभी कैश नहीं होते)। नीचे अतिरिक्त नियम जोड़ें, प्रति पंक्ति एक।','Exclude URL paths (prefix match)'=>'URL पथ बाहर रखें (उपसर्ग मिलान)','Exclude query keys'=>'क्वेरी की बाहर रखें','Exclude cookie name prefixes'=>'कुकी नाम उपसर्ग बाहर रखें','Maintenance'=>'रखरखाव','Purge everything now'=>'अभी सब कुछ पर्ज करें','detected'=>'पता चला','not detected'=>'पता नहीं चला','phpredis extension missing'=>'phpredis एक्सटेंशन अनुपलब्ध','active'=>'सक्रिय','inactive'=>'निष्क्रिय','LiteSpeed cache:'=>'LiteSpeed कैश:','Redis object cache:'=>'Redis ऑब्जेक्ट कैश:','The Redis PHP extension (phpredis) is not available on this server, so the object cache cannot be enabled.'=>'इस सर्वर पर Redis PHP एक्सटेंशन (phpredis) उपलब्ध नहीं है, इसलिए ऑब्जेक्ट कैश सक्षम नहीं किया जा सकता।','Another object-cache drop-in is already installed. Remove it before enabling the Zinn® object cache.'=>'एक अन्य ऑब्जेक्ट-कैश ड्रॉप-इन पहले से इंस्टॉल 